Translate("ruRU", "ragefire-chasm", {
	title = "Огненная пропасть",
	aliases = { "Пропасть" },
	sections = {
		{
			title = "Обзор",
			text = [=[Огненная пропасть — сеть пылающих пещер под {link:orgrimmar}Оргриммаром{/link}. Реки лавы освещают ее туннели, и жар глубин поднимается сквозь камень. В нее ведет проход на дне Расселины Теней. Немногие жители столицы знают, что лежит у них под ногами. У тех, кто знает, есть причина бояться, ибо пропасть — дом диких {link:troggs}трогг{/link}ов и тайного культа, который замышляет падение {link:horde}Орды{/link}.]=],
		},
		{
			title = "Истоки",
